import {
  Injectable,
  Logger,
  OnModuleInit,
  OnModuleDestroy,
} from '@nestjs/common';
import { Worker, Job } from 'bullmq';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { File, ProcessStatus, FileType } from './file.entity';
import { FileParserService, ParseResult } from './file-parser.service';
import { OcrService, OcrResult } from './ocr.service';
import { BullMQConfigService, FileProcessingJob } from './bullmq.config';

@Injectable()
export class FileProcessingWorker implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(FileProcessingWorker.name);
  private worker: Worker;
  private dlqWorker: Worker;

  constructor(
    private readonly bullMQConfig: BullMQConfigService,
    private readonly fileParserService: FileParserService,
    private readonly ocrService: OcrService,
    @InjectRepository(File)
    private readonly fileRepository: Repository<File>,
  ) {}

  onModuleInit() {
    // 主队列工作器
    this.worker = new Worker(
      this.bullMQConfig['fileProcessingQueue'].name,
      this.processFileJob.bind(this),
      {
        connection: this.bullMQConfig.getRedisConnection(),
        concurrency: 3, // 并发处理3个任务
        limiter: {
          max: 100,
          duration: 60000, // 每分钟最多处理100个任务
        },
      },
    );

    // 死信队列工作器
    this.dlqWorker = new Worker(
      this.bullMQConfig['fileProcessingDLQ'].name,
      this.handleDLQJob.bind(this),
      {
        connection: this.bullMQConfig.getRedisConnection(),
        concurrency: 1, // DLQ任务单线程处理
      },
    );

    // 设置工作器事件监听
    this.setupWorkerEvents(this.worker, 'Main Queue');
    this.setupWorkerEvents(this.dlqWorker, 'DLQ');

    this.logger.log('File processing workers initialized');
  }

  async onModuleDestroy() {
    if (this.worker) {
      await this.worker.close();
    }
    if (this.dlqWorker) {
      await this.dlqWorker.close();
    }
    this.logger.log('File processing workers closed');
  }

  /**
   * 处理文件任务
   */
  private async processFileJob(job: Job<FileProcessingJob>): Promise<any> {
    const { fileId, fileType, processType } = job.data;

    this.logger.log(`Processing file job: ${fileId}, type: ${processType}`);

    try {
      // 获取文件记录
      const file = await this.fileRepository.findOne({ where: { id: fileId } });
      if (!file) {
        throw new Error(`File not found: ${fileId}`);
      }

      // 更新状态为处理中
      file.processStatus = ProcessStatus.PROCESSING;
      file.metadata.lastProcessingAttempt = new Date();
      file.metadata.retryCount = (file.metadata.retryCount || 0) + 1;
      await this.fileRepository.save(file);

      let parseResult: ParseResult | null = null;
      let ocrResult: OcrResult | null = null;

      // 文件内容解析
      if (fileType !== FileType.IMAGE || processType === 'full') {
        parseResult = await this.fileParserService.parseFile(file);

        if (!parseResult.success) {
          throw new Error(`File parsing failed: ${parseResult.error}`);
        }
      }

      // OCR处理（仅图片文件或完整处理）
      if (
        fileType === FileType.IMAGE &&
        (processType === 'ocr' || processType === 'full')
      ) {
        ocrResult = await this.ocrService.performOcr(file);

        if (!ocrResult.success) {
          this.logger.warn(
            `OCR processing failed for file ${fileId}: ${ocrResult.error}`,
          );
          // OCR失败不视为致命错误，继续处理
        }
      }

      // 合并处理结果
      const finalContent = this.mergeProcessingResults(
        file,
        parseResult,
        ocrResult,
      );

      // 更新文件记录
      file.extractedContent = finalContent;
      file.processStatus = ProcessStatus.COMPLETED;
      file.metadata.extractedAt = new Date();
      file.metadata.ocrProcessed = !!ocrResult?.success;
      file.metadata.parseError = undefined;

      // 合并元数据
      if (parseResult?.metadata) {
        file.metadata = { ...file.metadata, ...parseResult.metadata };
      }
      if (ocrResult?.metadata) {
        file.metadata = { ...file.metadata, ...ocrResult.metadata };
      }

      await this.fileRepository.save(file);

      this.logger.log(`File processing completed successfully: ${fileId}`);

      return {
        success: true,
        fileId,
        processingType: processType,
        contentLength: finalContent.length,
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(`File processing failed: ${fileId}`, error);

      // 更新文件状态为失败
      try {
        const file = await this.fileRepository.findOne({
          where: { id: fileId },
        });
        if (file) {
          file.processStatus = ProcessStatus.FAILED;
          file.metadata.parseError = errorMessage;
          file.metadata.lastProcessingAttempt = new Date();

          // 如果重试次数过多，标记清理失败时间
          if ((file.metadata.retryCount || 0) >= 5) {
            file.cleanupFailedAt = new Date();
          }

          await this.fileRepository.save(file);
        }
      } catch (saveError) {
        this.logger.error(
          `Failed to update file status after processing error: ${fileId}`,
          saveError,
        );
      }

      throw error; // 重新抛出错误，让BullMQ处理重试逻辑
    }
  }

  /**
   * 处理死信队列任务
   */
  private async handleDLQJob(job: Job<FileProcessingJob>): Promise<any> {
    const { fileId, retryCount = 0 } = job.data;

    this.logger.log(
      `Processing DLQ job: ${fileId}, retry count: ${retryCount}`,
    );

    try {
      const file = await this.fileRepository.findOne({ where: { id: fileId } });
      if (!file) {
        this.logger.warn(`DLQ job for non-existent file: ${fileId}`);
        return { success: false, reason: 'File not found' };
      }

      // 检查是否应该重试
      if (retryCount >= 5) {
        this.logger.log(
          `File ${fileId} exceeded maximum retry attempts, marking as permanently failed`,
        );
        file.processStatus = ProcessStatus.FAILED;
        file.cleanupFailedAt = new Date();
        file.metadata.parseError = 'Maximum retry attempts exceeded';
        await this.fileRepository.save(file);

        return { success: false, reason: 'Maximum retry attempts exceeded' };
      }

      // 延迟重试
      const delay = Math.min(300000, 5000 * Math.pow(2, retryCount)); // 最大延迟5分钟

      setTimeout(async () => {
        try {
          await this.bullMQConfig.addFileProcessingJob(job.data, { delay });
          this.logger.log(
            `DLQ job ${fileId} rescheduled with delay: ${delay}ms`,
          );
        } catch (error) {
          this.logger.error(`Failed to reschedule DLQ job: ${fileId}`, error);
        }
      }, 1000);

      return { success: true, action: 'rescheduled', delay };
    } catch (error) {
      this.logger.error(`DLQ job processing failed: ${fileId}`, error);
      throw error;
    }
  }

  /**
   * 合并处理结果
   */
  private mergeProcessingResults(
    file: File,
    parseResult: ParseResult | null,
    ocrResult: OcrResult | null,
  ): string {
    const contents: string[] = [];

    // 添加文件解析内容
    if (parseResult?.success && parseResult.content) {
      contents.push(parseResult.content);
    }

    // 添加OCR内容
    if (ocrResult?.success && ocrResult.text) {
      const ocrHeader =
        file.fileType === FileType.IMAGE ? '' : '\n--- OCR识别内容 ---\n';
      contents.push(ocrHeader + ocrResult.text);
    }

    return contents.join('\n\n').trim();
  }

  /**
   * 设置工作器事件监听
   */
  private setupWorkerEvents(worker: Worker, workerName: string): void {
    worker.on('completed', (job) => {
      this.logger.log(
        `${workerName} job completed: ${job?.id} (fileId: ${job?.data?.fileId})`,
      );
    });

    worker.on('failed', (job, err) => {
      this.logger.error(
        `${workerName} job failed: ${job?.id} (fileId: ${job?.data?.fileId})`,
        err,
      );

      // 如果是主队列失败且重试次数超过阈值，添加到死信队列
      if (workerName === 'Main Queue' && job && job.data?.retryCount >= 3) {
        this.bullMQConfig['fileProcessingDLQ'].add('dlq-job', job.data, {
          delay: 0,
          attempts: 1,
        });
      }
    });

    worker.on('error', (err) => {
      this.logger.error(`${workerName} worker error`, err);
    });

    worker.on('stalled', (jobId: string) => {
      this.logger.warn(`${workerName} job stalled: ${jobId}`);
    });
  }

  /**
   * 获取工作器状态
   */
  async getWorkerStatus() {
    const mainWorkerActive = this.worker?.isRunning() || false;
    const dlqWorkerActive = this.dlqWorker?.isRunning() || false;

    return {
      mainWorker: {
        active: mainWorkerActive,
        concurrency: this.worker?.opts.concurrency || 0,
      },
      dlqWorker: {
        active: dlqWorkerActive,
        concurrency: this.dlqWorker?.opts.concurrency || 0,
      },
    };
  }

  /**
   * 手动触发文件重新处理
   */
  async reprocessFile(
    fileId: string,
    processType: 'extract' | 'ocr' | 'full' = 'full',
  ): Promise<void> {
    const file = await this.fileRepository.findOne({ where: { id: fileId } });
    if (!file) {
      throw new Error(`File not found: ${fileId}`);
    }

    const jobData: FileProcessingJob = {
      fileId,
      userId: file.userId,
      originalName: file.originalName,
      storageKey: file.storageKey,
      fileType: file.fileType,
      processType,
      retryCount: 0,
    };

    await this.bullMQConfig.addFileProcessingJob(jobData);
    this.logger.log(
      `Manual reprocessing initiated for file: ${fileId}, type: ${processType}`,
    );
  }

  /**
   * 清理死信队列
   */
  async cleanupDLQ(maxAge: number = 7 * 24 * 60 * 60 * 1000): Promise<void> {
    await this.bullMQConfig.cleanDLQ(maxAge);
    this.logger.log(`DLQ cleanup completed for jobs older than ${maxAge}ms`);
  }

  /**
   * 暂停工作器
   */
  async pauseWorkers(): Promise<void> {
    if (this.worker) {
      await this.worker.pause();
    }
    if (this.dlqWorker) {
      await this.dlqWorker.pause();
    }
    this.logger.log('Workers paused');
  }

  /**
   * 恢复工作器
   */
  async resumeWorkers(): Promise<void> {
    if (this.worker) {
      await this.worker.resume();
    }
    if (this.dlqWorker) {
      await this.dlqWorker.resume();
    }
    this.logger.log('Workers resumed');
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource, LessThan } from 'typeorm';
import { Cron, CronExpression } from '@nestjs/schedule';
import { File, ProcessStatus, FileType } from './file.entity';
import { DownloadLog, DownloadResult } from './download-log.entity';
import {
  StorageService,
  UploadResult,
  DownloadResult as StorageDownloadResult,
} from './storage.service';
import { BullMQConfigService, FileProcessingJob } from './bullmq.config';
import archiver from 'archiver';
import { PassThrough } from 'stream';
import * as path from 'path';
import * as fileType from 'file-type';

export interface UploadFileDto {
  buffer: Buffer;
  originalName: string;
  mimeType: string;
  userId: string;
}

export interface FileListQuery {
  userId: string;
  page?: number;
  limit?: number;
  fileType?: FileType;
  processStatus?: ProcessStatus;
  search?: string;
}

export interface FileStatsDto {
  totalFiles: number;
  totalSize: number;
  processingFiles: number;
  completedFiles: number;
  failedFiles: number;
  filesByType: Record<FileType, number>;
}

@Injectable()
export class FilesService {
  private readonly logger = new Logger(FilesService.name);

  constructor(
    @InjectRepository(File)
    private readonly fileRepository: Repository<File>,
    @InjectRepository(DownloadLog)
    private readonly downloadLogRepository: Repository<DownloadLog>,
    private readonly storageService: StorageService,
    private readonly bullMQConfig: BullMQConfigService,
    private readonly dataSource: DataSource,
  ) {}

  /**
   * 上传文件 - 实现数据一致性优化
   * 策略：先上传到对象存储，成功后再创建数据库记录
   */
  async uploadFile(uploadDto: UploadFileDto): Promise<File> {
    const startTime = Date.now();
    let storageResult: UploadResult | null = null;
    let fileRecord: File | null = null;

    try {
      // 1. 验证文件类型和大小（包含安全检查）
      await this.validateFile(
        uploadDto.originalName,
        uploadDto.mimeType,
        uploadDto.buffer,
      );

      // 2. 先上传到对象存储
      this.logger.log(`Uploading file ${uploadDto.originalName} to storage...`);
      storageResult = await this.storageService.uploadFile(
        uploadDto.buffer,
        uploadDto.originalName,
        uploadDto.mimeType,
        uploadDto.userId,
      );
      this.logger.log(`File uploaded to storage: ${storageResult.key}`);

      // 3. 创建数据库记录
      const expiresAt = new Date();
      expiresAt.setHours(expiresAt.getHours() + 24); // 24小时后过期

      fileRecord = this.fileRepository.create({
        filename: uploadDto.originalName,
        originalName: uploadDto.originalName,
        fileType: this.detectFileType(
          uploadDto.originalName,
          uploadDto.mimeType,
        ),
        mimeType: uploadDto.mimeType,
        size: uploadDto.buffer.length,
        path: storageResult.key,
        userId: uploadDto.userId,
        processStatus: ProcessStatus.PENDING,
        storageKey: storageResult.key,
        storageProvider: storageResult.provider,
        expiresAt,
        metadata: {
          lastProcessingAttempt: new Date(),
          retryCount: 0,
        },
      });

      // 4. 保存到数据库
      fileRecord = await this.fileRepository.save(fileRecord);
      this.logger.log(`File record created: ${fileRecord.id}`);

      // 5. 添加到处理队列
      await this.addFileToProcessingQueue(fileRecord);

      // 6. 记录处理耗时
      const processingDuration = Date.now() - startTime;
      if (fileRecord.metadata) {
        fileRecord.metadata.processingDuration = processingDuration;
        await this.fileRepository.save(fileRecord);
      }

      return fileRecord;
    } catch (error) {
      this.logger.error(
        `Failed to upload file ${uploadDto.originalName}`,
        error,
      );

      // 数据一致性恢复：如果存储成功但数据库失败，尝试删除存储的文件
      if (storageResult && !fileRecord) {
        try {
          await this.storageService.deleteFile(storageResult.key);
          this.logger.log(`Cleaned up storage file: ${storageResult.key}`);
        } catch (cleanupError) {
          this.logger.error(
            `Failed to cleanup storage file: ${storageResult.key}`,
            cleanupError,
          );
        }
      }

      if (error instanceof BadRequestException) {
        throw error;
      }

      throw new InternalServerErrorException(
        `File upload failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  /**
   * 下载文件 - 实现安全下载和日志记录
   */
  async downloadFile(
    fileId: string,
    userId: string,
    clientIp: string,
    userAgent?: string,
  ): Promise<StorageDownloadResult> {
    const startTime = Date.now();
    const downloadLog: DownloadLog | null = null;

    try {
      // 1. 获取文件信息
      const file = await this.fileRepository.findOne({
        where: { id: fileId, userId },
      });

      if (!file) {
        // 记录失败日志
        await this.createDownloadLog(
          fileId,
          userId,
          clientIp,
          userAgent || '',
          DownloadResult.FAILED_NOT_FOUND,
          'File not found',
        );
        throw new NotFoundException('File not found');
      }

      // 2. 检查存储中的文件是否存在
      const storageExists = await this.storageService.fileExists(
        file.storageKey,
      );
      if (!storageExists) {
        await this.createDownloadLog(
          fileId,
          userId,
          clientIp,
          userAgent || '',
          DownloadResult.FAILED_NOT_FOUND,
          'File not found in storage',
        );
        throw new NotFoundException('File not found in storage');
      }

      // 3. 从存储下载文件
      const downloadResult = await this.storageService.downloadFile(
        file.storageKey,
        file.originalName,
      );

      // 4. 记录成功日志
      const responseTime = Date.now() - startTime;
      await this.createDownloadLog(
        fileId,
        userId,
        clientIp,
        userAgent || '',
        DownloadResult.SUCCESS,
        undefined,
        downloadResult.contentLength,
        responseTime,
      );

      this.logger.log(
        `File downloaded successfully: ${fileId} by user ${userId}`,
      );
      return downloadResult;
    } catch (error) {
      // 记录失败日志（如果还没有记录的话）
      if (!downloadLog) {
        const failureReason =
          error instanceof NotFoundException ? error.message : 'System error';
        await this.createDownloadLog(
          fileId,
          userId,
          clientIp,
          userAgent || '',
          DownloadResult.FAILED_SYSTEM_ERROR,
          failureReason,
        );
      }

      throw error;
    }
  }

  /**
   * 获取用户文件列表
   */
  async getFileList(
    query: FileListQuery,
  ): Promise<{ files: File[]; total: number; page: number; limit: number }> {
    const {
      userId,
      page = 1,
      limit = 20,
      fileType,
      processStatus,
      search,
    } = query;

    const queryBuilder = this.fileRepository
      .createQueryBuilder('file')
      .where('file.userId = :userId', { userId });

    // 文件类型过滤
    if (fileType) {
      queryBuilder.andWhere('file.fileType = :fileType', { fileType });
    }

    // 处理状态过滤
    if (processStatus) {
      queryBuilder.andWhere('file.processStatus = :processStatus', {
        processStatus,
      });
    }

    // 搜索过滤
    if (search) {
      queryBuilder.andWhere(
        '(file.originalName ILIKE :search OR file.extractedContent ILIKE :search)',
        { search: `%${search}%` },
      );
    }

    // 总数统计
    const total = await queryBuilder.getCount();

    // 分页查询
    const files = await queryBuilder
      .orderBy('file.createdAt', 'DESC')
      .skip((page - 1) * limit)
      .take(limit)
      .getMany();

    return { files, total, page, limit };
  }

  /**
   * 获取文件详细信息
   */
  async getFileById(fileId: string, userId: string): Promise<File> {
    const file = await this.fileRepository.findOne({
      where: { id: fileId, userId },
    });

    if (!file) {
      throw new NotFoundException('File not found');
    }

    return file;
  }

  /**
   * 删除文件 - 实现级联删除
   */
  async deleteFile(fileId: string, userId: string): Promise<void> {
    const file = await this.fileRepository.findOne({
      where: { id: fileId, userId },
    });

    if (!file) {
      throw new NotFoundException('File not found');
    }

    try {
      // 使用数据库事务确保数据一致性
      await this.dataSource.transaction(async (manager) => {
        // 1. 删除下载日志
        await manager.delete(DownloadLog, { fileId });

        // 2. 删除数据库中的文件记录
        await manager.delete(File, { id: fileId });

        // 3. 删除存储中的文件
        await this.storageService.deleteFile(file.storageKey);
      });

      this.logger.log(`File deleted successfully: ${fileId}`);
    } catch (error) {
      this.logger.error(`Failed to delete file ${fileId}`, error);
      throw new InternalServerErrorException(
        `File deletion failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  /**
   * 获取文件统计信息
   */
  async getFileStats(userId: string): Promise<FileStatsDto> {
    const stats = await this.fileRepository
      .createQueryBuilder('file')
      .select('COUNT(file.id)', 'totalFiles')
      .addSelect('SUM(file.size)', 'totalSize')
      .addSelect(
        'COUNT(CASE WHEN file.processStatus = :processing THEN 1 END)',
        'processingFiles',
      )
      .addSelect(
        'COUNT(CASE WHEN file.processStatus = :completed THEN 1 END)',
        'completedFiles',
      )
      .addSelect(
        'COUNT(CASE WHEN file.processStatus = :failed THEN 1 END)',
        'failedFiles',
      )
      .where('file.userId = :userId', { userId })
      .setParameters({
        processing: ProcessStatus.PROCESSING,
        completed: ProcessStatus.COMPLETED,
        failed: ProcessStatus.FAILED,
      })
      .getRawOne();

    // 按类型统计
    const filesByType = await this.fileRepository
      .createQueryBuilder('file')
      .select('file.fileType', 'type')
      .addSelect('COUNT(file.id)', 'count')
      .where('file.userId = :userId', { userId })
      .groupBy('file.fileType')
      .getRawMany();

    const typeStats: Record<FileType, number> = {
      [FileType.TEXT]: 0,
      [FileType.IMAGE]: 0,
      [FileType.PDF]: 0,
      [FileType.WORD]: 0,
      [FileType.MARKDOWN]: 0,
    };

    filesByType.forEach((item: { type: FileType; count: string }) => {
      typeStats[item.type] = parseInt(item.count);
    });

    return {
      totalFiles: parseInt(stats.totalFiles) || 0,
      totalSize: parseInt(stats.totalSize) || 0,
      processingFiles: parseInt(stats.processingFiles) || 0,
      completedFiles: parseInt(stats.completedFiles) || 0,
      failedFiles: parseInt(stats.failedFiles) || 0,
      filesByType: typeStats,
    };
  }

  /**
   * 重新处理文件
   */
  async reprocessFile(fileId: string, userId: string): Promise<void> {
    const file = await this.fileRepository.findOne({
      where: { id: fileId, userId },
    });

    if (!file) {
      throw new NotFoundException('File not found');
    }

    // 重置处理状态
    file.processStatus = ProcessStatus.PENDING;
    if (file.metadata) {
      file.metadata.lastProcessingAttempt = new Date();
      file.metadata.retryCount = 0;
    }
    await this.fileRepository.save(file);

    // 重新添加到处理队列
    await this.addFileToProcessingQueue(file);

    this.logger.log(`File reprocessing initiated: ${fileId}`);
  }

  /**
   * 获取队列状态
   */
  async getQueueStatus() {
    return await this.bullMQConfig.getQueueStats();
  }

  /**
   * 重试死信队列中的任务
   */
  async retryDLQJob(jobId: string, userId: string) {
    // 这里可以添加权限检查，确保用户只能重试自己的任务
    await this.bullMQConfig.retryDLQJob(jobId);
  }

  /**
   * 验证文件（增强安全性）
   */
  private async validateFile(
    filename: string,
    mimeType: string,
    buffer: Buffer,
  ): Promise<void> {
    // 1. 文件大小限制 (100MB)
    const maxSize = 100 * 1024 * 1024;
    if (buffer.length > maxSize) {
      throw new BadRequestException(
        `文件大小超过限制（最大 ${maxSize / 1024 / 1024}MB）`,
      );
    }

    // 2. 文件名清理（防止路径遍历攻击）
    const sanitizedFilename = path.basename(filename);
    if (sanitizedFilename !== filename) {
      throw new BadRequestException('文件名包含非法字符');
    }

    // 3. 文件名长度限制
    if (sanitizedFilename.length > 255) {
      throw new BadRequestException('文件名过长（最大255字符）');
    }

    // 4. 扩展名白名单验证
    const allowedExtensions = [
      '.txt',
      '.md',
      '.pdf',
      '.jpg',
      '.jpeg',
      '.png',
      '.gif',
      '.doc',
      '.docx',
    ];
    const ext = path.extname(sanitizedFilename).toLowerCase();
    if (!ext || !allowedExtensions.includes(ext)) {
      throw new BadRequestException(
        `不支持的文件扩展名: ${ext || '(无扩展名)'}`,
      );
    }

    // 5. MIME 类型白名单
    const allowedMimeTypes = [
      'text/plain',
      'text/markdown',
      'image/jpeg',
      'image/png',
      'image/gif',
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    ];

    if (!allowedMimeTypes.includes(mimeType)) {
      throw new BadRequestException(`不支持的 MIME 类型: ${mimeType}`);
    }

    // 6. 验证文件魔术字节（真实文件类型）
    try {
      const detectedType = await fileType.fromBuffer(buffer);

      // 对于某些文本文件，file-type 可能无法检测，这是正常的
      if (detectedType) {
        // 验证检测到的类型是否在允许列表中
        const detectedMimeType = detectedType.mime;

        // 特殊处理：Word 文档的 MIME 类型可能不同
        const isWordDoc =
          detectedMimeType === 'application/zip' &&
          (mimeType === 'application/msword' ||
            mimeType ===
              'application/vnd.openxmlformats-officedocument.wordprocessingml.document');

        if (!allowedMimeTypes.includes(detectedMimeType) && !isWordDoc) {
          throw new BadRequestException(
            `文件内容与声明类型不符。检测到的类型: ${detectedMimeType}`,
          );
        }

        // 验证扩展名与实际类型是否匹配
        if (detectedType.ext && ext.slice(1) !== detectedType.ext) {
          // 允许 jpg 和 jpeg 互换
          const isJpegVariant =
            (ext === '.jpg' || ext === '.jpeg') && detectedType.ext === 'jpg';

          if (!isJpegVariant && !isWordDoc) {
            throw new BadRequestException(
              `文件扩展名与实际类型不符。期望: ${detectedType.ext}, 实际: ${ext}`,
            );
          }
        }
      }
    } catch (error) {
      // 如果是我们抛出的 BadRequestException，继续抛出
      if (error instanceof BadRequestException) {
        throw error;
      }
      // 其他错误记录日志但不阻止上传（某些文件类型可能无法检测）
      this.logger.warn(`文件类型检测失败: ${filename}`, error);
    }
  }

  /**
   * 检测文件类型
   */
  private detectFileType(filename: string, mimeType: string): FileType {
    const extension = filename.split('.').pop()?.toLowerCase();

    switch (mimeType) {
      case 'text/plain':
        return FileType.TEXT;
      case 'text/markdown':
        return FileType.MARKDOWN;
      case 'image/jpeg':
      case 'image/png':
      case 'image/gif':
        return FileType.IMAGE;
      case 'application/pdf':
        return FileType.PDF;
      case 'application/msword':
      case 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
        return FileType.WORD;
      default:
        // 根据扩展名推断
        if (extension === 'md') return FileType.MARKDOWN;
        if (extension === 'txt') return FileType.TEXT;
        if (extension && ['jpg', 'jpeg', 'png', 'gif'].includes(extension))
          return FileType.IMAGE;
        if (extension === 'pdf') return FileType.PDF;
        if (extension && ['doc', 'docx'].includes(extension))
          return FileType.WORD;

        throw new BadRequestException(
          `Cannot determine file type for: ${filename}`,
        );
    }
  }

  /**
   * 添加文件到处理队列
   */
  private async addFileToProcessingQueue(file: File): Promise<void> {
    const jobData: FileProcessingJob = {
      fileId: file.id,
      userId: file.userId,
      originalName: file.originalName,
      storageKey: file.storageKey,
      fileType: file.fileType,
      processType: 'full', // 默认完整处理
      retryCount: 0,
    };

    await this.bullMQConfig.addFileProcessingJob(jobData);
    this.logger.log(`File added to processing queue: ${file.id}`);
  }

  /**
   * 批量下载文件（ZIP格式）
   */
  async batchDownloadFiles(
    fileIds: string[],
    userId: string,
  ): Promise<PassThrough> {
    try {
      // 1. 验证所有文件是否存在且属于该用户
      const files = await this.fileRepository.find({
        where: fileIds.map((id) => ({ id, userId })),
      });

      if (files.length === 0) {
        throw new NotFoundException('No files found');
      }

      if (files.length !== fileIds.length) {
        throw new BadRequestException('Some files not found or access denied');
      }

      // 2. 创建ZIP流
      const archive = archiver('zip', {
        zlib: { level: 6 }, // 压缩级别
      });

      const passThrough = new PassThrough();
      archive.pipe(passThrough);

      // 3. 添加文件到ZIP
      for (const file of files) {
        try {
          const downloadResult = await this.storageService.downloadFile(
            file.storageKey,
            file.originalName,
          );

          // 使用原始文件名添加到ZIP
          archive.append(downloadResult.stream, { name: file.originalName });

          this.logger.log(`Added file to ZIP: ${file.originalName}`);
        } catch (error) {
          this.logger.error(
            `Failed to add file to ZIP: ${file.originalName}`,
            error,
          );
          // 继续处理其他文件
        }
      }

      // 4. 完成ZIP创建
      archive.finalize();

      this.logger.log(
        `Batch download ZIP created for ${files.length} files by user ${userId}`,
      );

      return passThrough;
    } catch (error) {
      this.logger.error('Batch download failed', error);
      throw error;
    }
  }

  /**
   * 文件过期清理定时任务（每小时执行一次）
   */
  @Cron(CronExpression.EVERY_HOUR)
  async cleanupExpiredFiles(): Promise<void> {
    this.logger.log('Starting expired files cleanup task...');

    try {
      // 查询已过期的文件
      const expiredFiles = await this.fileRepository.find({
        where: {
          expiresAt: LessThan(new Date()),
        },
      });

      if (expiredFiles.length === 0) {
        this.logger.log('No expired files found');
        return;
      }

      this.logger.log(`Found ${expiredFiles.length} expired files to clean up`);

      let successCount = 0;
      let failureCount = 0;

      // 逐个删除过期文件
      for (const file of expiredFiles) {
        try {
          // 先从存储删除
          await this.storageService.deleteFile(file.storageKey);

          // 删除下载日志
          await this.downloadLogRepository.delete({ fileId: file.id });

          // 删除数据库记录
          await this.fileRepository.delete({ id: file.id });

          successCount++;
          this.logger.log(`Cleaned up expired file: ${file.id}`);
        } catch (error) {
          failureCount++;
          this.logger.error(
            `Failed to cleanup expired file: ${file.id}`,
            error,
          );

          // 标记清理失败
          await this.fileRepository.update(file.id, {
            processStatus: ProcessStatus.CLEANUP_FAILED,
            cleanupFailedAt: new Date(),
          });
        }
      }

      this.logger.log(
        `Expired files cleanup completed: ${successCount} succeeded, ${failureCount} failed`,
      );
    } catch (error) {
      this.logger.error('Expired files cleanup task failed', error);
    }
  }

  /**
   * 创建下载日志
   */
  private async createDownloadLog(
    fileId: string,
    userId: string,
    clientIp: string,
    userAgent: string,
    result: DownloadResult,
    failureReason?: string,
    downloadSize?: number,
    responseTimeMs?: number,
  ): Promise<void> {
    try {
      const downloadLog = this.downloadLogRepository.create({
        fileId,
        userId,
        clientIp,
        userAgent,
        result,
        failureReason,
        downloadSize,
        responseTimeMs,
      });

      await this.downloadLogRepository.save(downloadLog);
    } catch (error) {
      this.logger.error('Failed to create download log', error);
      // 不抛出异常，避免影响主要功能
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { StorageService } from './storage.service';
import { FileType, File } from './file.entity';
import * as fs from 'fs';
import * as path from 'path';
import * as util from 'util';
import { exec } from 'child_process';
import axios from 'axios';
import * as crypto from 'crypto';

const execAsync = util.promisify(exec);

export interface OcrResult {
  success: boolean;
  text?: string;
  confidence?: number;
  metadata?: {
    processingDuration?: number;
    language?: string;
    textBlocks?: number;
  };
  error?: string;
}

export interface OcrConfig {
  enabled: boolean;
  provider: 'aliyun' | 'tesseract';
  aliyun?: {
    accessKeyId: string;
    accessKeySecret: string;
    endpoint: string;
    region: string;
  };
  tesseract?: {
    executablePath: string;
    language: string;
  };
}

@Injectable()
export class OcrService {
  private readonly logger = new Logger(OcrService.name);
  private readonly config: OcrConfig;
  private readonly tempDir: string;

  constructor(
    private readonly storageService: StorageService,
    private readonly configService: ConfigService,
  ) {
    this.config = this.loadOcrConfig();
    this.tempDir = this.configService.get<string>(
      'FILE_TEMP_DIR',
      '/tmp/flowgenall',
    );
    this.ensureTempDir();
  }

  /**
   * 加载OCR配置
   */
  private loadOcrConfig(): OcrConfig {
    const enabled = this.configService.get<boolean>('OCR_ENABLED', false);
    const provider = this.configService.get<string>(
      'OCR_PROVIDER',
      'tesseract',
    ) as 'aliyun' | 'tesseract';

    if (!enabled) {
      return { enabled: false, provider };
    }

    if (provider === 'aliyun') {
      const accessKeyId = this.configService.get<string>(
        'ALIYUN_OCR_ACCESS_KEY_ID',
      );
      const accessKeySecret = this.configService.get<string>(
        'ALIYUN_OCR_ACCESS_KEY_SECRET',
      );
      const endpoint = this.configService.get<string>(
        'ALIYUN_OCR_ENDPOINT',
        'ocr-api.cn-hangzhou.aliyuncs.com',
      );
      const region = this.configService.get<string>(
        'ALIYUN_OCR_REGION',
        'cn-hangzhou',
      );

      if (!accessKeyId || !accessKeySecret) {
        this.logger.warn(
          'Aliyun OCR credentials not provided, falling back to tesseract',
        );
        return {
          enabled: true,
          provider: 'tesseract',
          tesseract: {
            executablePath: this.configService.get<string>(
              'TESSERACT_PATH',
              'tesseract',
            ),
            language: this.configService.get<string>(
              'TESSERACT_LANGUAGE',
              'chi_sim+eng',
            ),
          },
        };
      }

      return {
        enabled: true,
        provider: 'aliyun',
        aliyun: {
          accessKeyId,
          accessKeySecret,
          endpoint,
          region,
        },
      };
    } else {
      return {
        enabled: true,
        provider: 'tesseract',
        tesseract: {
          executablePath: this.configService.get<string>(
            'TESSERACT_PATH',
            'tesseract',
          ),
          language: this.configService.get<string>(
            'TESSERACT_LANGUAGE',
            'chi_sim+eng',
          ),
        },
      };
    }
  }

  /**
   * 执行OCR识别
   */
  async performOcr(file: File): Promise<OcrResult> {
    const startTime = Date.now();

    try {
      if (!this.config.enabled) {
        return {
          success: false,
          error: 'OCR service is not enabled',
        };
      }

      if (file.fileType !== FileType.IMAGE) {
        return {
          success: false,
          error: 'OCR is only supported for image files',
        };
      }

      this.logger.log(`Starting OCR for file: ${file.id}`);

      let result: OcrResult;

      if (this.config.provider === 'aliyun') {
        result = await this.performAliyunOcr(file);
      } else {
        result = await this.performTesseractOcr(file);
      }

      // 添加处理耗时
      if (result.metadata) {
        result.metadata.processingDuration = Date.now() - startTime;
      }

      this.logger.log(
        `OCR completed for file: ${file.id}, success: ${result.success}`,
      );
      return result;
    } catch (error) {
      this.logger.error(`OCR failed for file: ${file.id}`, error);
      return {
        success: false,
        error: error.message,
        metadata: {
          processingDuration: Date.now() - startTime,
        },
      };
    }
  }

  /**
   * 使用阿里云OCR进行识别
   */
  private async performAliyunOcr(file: File): Promise<OcrResult> {
    try {
      if (!this.config.aliyun) {
        throw new Error('Aliyun OCR configuration is missing');
      }

      // 下载图片到临时文件
      const downloadResult = await this.storageService.downloadFile(
        file.storageKey,
        file.originalName,
      );
      const tempFilePath = await this.saveToTempFile(
        file.originalName,
        downloadResult.stream,
      );

      try {
        // 读取图片为base64
        const imageBuffer = await fs.promises.readFile(tempFilePath);
        const imageBase64 = imageBuffer.toString('base64');

        // 构建阿里云OCR请求
        const requestBody = JSON.stringify({
          image: imageBase64,
          configure: {
            min_size: 16,
            output_prob: false,
            output_keypoints: false,
            skip_detection: false,
            without_txt: false,
            multi_crop: true,
          },
        });

        // 生成签名
        const method = 'POST';
        const uri = '/api/v1/ocr/general/text';
        const host = this.config.aliyun.endpoint
          .replace('https://', '')
          .replace('http://', '');
        const timestamp = new Date().toISOString();
        const nonce = crypto.randomBytes(16).toString('hex');

        const stringToSign = [
          method,
          uri,
          host,
          timestamp,
          nonce,
          crypto.createHash('sha256').update(requestBody).digest('hex'),
        ].join('\n');

        const signature = crypto
          .createHmac('sha256', this.config.aliyun.accessKeySecret)
          .update(stringToSign)
          .digest('base64');

        const authorization = `acs ${this.config.aliyun.accessKeyId}:${signature}`;

        // 发送请求
        const response = await axios.post(
          `https://${host}${uri}`,
          requestBody,
          {
            headers: {
              'Content-Type': 'application/json',
              Authorization: authorization,
              'X-Acs-Version': '2021-07-07',
              'X-Acs-Action': 'RecognizeGeneral',
              'X-Acs-Timestamp': timestamp,
              'X-Acs-Nonce': nonce,
            },
            timeout: 30000,
          },
        );

        const responseData = response.data as any;
        if (responseData.code !== 200) {
          throw new Error(`Aliyun OCR API error: ${responseData.message}`);
        }

        const data = responseData.data;
        const textBlocks = data.prism_wordsInfo || [];
        const extractedText = textBlocks
          .map((block: any) => block.word)
          .join('\n');

        return {
          success: true,
          text: extractedText.trim(),
          confidence: this.calculateAverageConfidence(textBlocks),
          metadata: {
            language: 'auto',
            textBlocks: textBlocks.length,
          },
        };
      } finally {
        await this.cleanupTempFile(tempFilePath);
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      return {
        success: false,
        error: `Aliyun OCR failed: ${errorMessage}`,
      };
    }
  }

  /**
   * 使用Tesseract进行OCR识别
   */
  private async performTesseractOcr(file: File): Promise<OcrResult> {
    try {
      if (!this.config.tesseract) {
        throw new Error('Tesseract configuration is missing');
      }

      // 下载图片到临时文件
      const downloadResult = await this.storageService.downloadFile(
        file.storageKey,
        file.originalName,
      );
      const tempFilePath = await this.saveToTempFile(
        file.originalName,
        downloadResult.stream,
      );

      try {
        // 执行Tesseract OCR
        const { stdout, stderr } = await execAsync(
          `"${this.config.tesseract.executablePath}" "${tempFilePath}" stdout -l ${this.config.tesseract.language}`,
          { timeout: 60000 },
        );

        if (stderr && !stderr.includes('Tesseract')) {
          throw new Error(`Tesseract error: ${stderr}`);
        }

        return {
          success: true,
          text: stdout.trim(),
          confidence: 0.8, // Tesseract不提供置信度，使用默认值
          metadata: {
            language: this.config.tesseract.language,
            textBlocks: stdout.split('\n').filter((line) => line.trim()).length,
          },
        };
      } finally {
        await this.cleanupTempFile(tempFilePath);
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      if (errorMessage.includes('command not found')) {
        return {
          success: false,
          error: 'Tesseract is not installed on the server',
        };
      }

      return {
        success: false,
        error: `Tesseract OCR failed: ${errorMessage}`,
      };
    }
  }

  /**
   * 计算平均置信度
   */
  private calculateAverageConfidence(textBlocks: any[]): number {
    if (!textBlocks.length) return 0;

    const totalConfidence = textBlocks.reduce((sum, block) => {
      return sum + (block.probability || 0);
    }, 0);

    return totalConfidence / textBlocks.length;
  }

  /**
   * 将流保存到临时文件
   */
  private async saveToTempFile(
    filename: string,
    stream: NodeJS.ReadableStream,
  ): Promise<string> {
    const tempFilePath = path.join(this.tempDir, `${Date.now()}_${filename}`);
    const chunks: Buffer[] = [];

    return new Promise((resolve, reject) => {
      stream.on('data', (chunk) => {
        chunks.push(chunk);
      });

      stream.on('end', async () => {
        try {
          const buffer = Buffer.concat(chunks);
          await fs.promises.writeFile(tempFilePath, buffer);
          resolve(tempFilePath);
        } catch (error) {
          reject(error);
        }
      });

      stream.on('error', reject);
    });
  }

  /**
   * 清理临时文件
   */
  private async cleanupTempFile(filePath: string): Promise<void> {
    try {
      await fs.promises.unlink(filePath);
    } catch (error) {
      this.logger.warn(`Failed to cleanup temp file: ${filePath}`, error);
    }
  }

  /**
   * 确保临时目录存在
   */
  private ensureTempDir(): void {
    try {
      if (!fs.existsSync(this.tempDir)) {
        fs.mkdirSync(this.tempDir, { recursive: true });
      }
    } catch (error) {
      this.logger.error(
        `Failed to create temp directory: ${this.tempDir}`,
        error,
      );
    }
  }

  /**
   * 检查OCR服务是否可用
   */
  async isOcrAvailable(): Promise<boolean> {
    if (!this.config.enabled) {
      return false;
    }

    if (this.config.provider === 'tesseract') {
      try {
        await execAsync(`"${this.config.tesseract!.executablePath}" --version`);
        return true;
      } catch (error) {
        return false;
      }
    }

    // 阿里云OCR的可用性检查可以通过简单的API调用来实现
    return true;
  }

  /**
   * 获取OCR配置信息
   */
  getOcrConfig(): OcrConfig {
    return {
      ...this.config,
      // 隐藏敏感信息
      aliyun: this.config.aliyun
        ? {
            ...this.config.aliyun,
            accessKeyId: '***',
            accessKeySecret: '***',
          }
        : undefined,
    };
  }

  /**
   * 清理临时目录
   */
  async cleanupTempDir(): Promise<void> {
    try {
      const files = await fs.promises.readdir(this.tempDir);
      const now = Date.now();
      const maxAge = 24 * 60 * 60 * 1000; // 24小时

      for (const file of files) {
        const filePath = path.join(this.tempDir, file);
        const stats = await fs.promises.stat(filePath);

        if (now - stats.mtime.getTime() > maxAge) {
          await this.cleanupTempFile(filePath);
        }
      }
    } catch (error) {
      this.logger.error('Failed to cleanup temp directory', error);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as Minio from 'minio';
import * as OSS from 'ali-oss';
import { Readable } from 'stream';

export interface StorageConfig {
  provider: 'minio' | 'oss';
  minio?: {
    endPoint: string;
    port: number;
    useSSL: boolean;
    accessKey: string;
    secretKey: string;
    bucketName: string;
  };
  oss?: {
    region: string;
    accessKeyId: string;
    accessKeySecret: string;
    bucketName: string;
    endpoint?: string;
  };
}

export interface UploadResult {
  key: string;
  url: string;
  size: number;
  provider: string;
}

export interface DownloadResult {
  stream: Readable;
  contentType: string;
  contentLength: number;
  filename: string;
}

@Injectable()
export class StorageService {
  private readonly logger = new Logger(StorageService.name);
  private minioClient: Minio.Client;
  private ossClient: OSS;
  private config: StorageConfig;

  constructor(private configService: ConfigService) {
    this.config = this.loadStorageConfig();
    this.initializeStorage();
  }

  /**
   * 加载存储配置
   */
  private loadStorageConfig(): StorageConfig {
    const provider = this.configService.get<string>(
      'STORAGE_PROVIDER',
      'minio',
    ) as 'minio' | 'oss';

    if (provider === 'minio') {
      const endPoint = this.configService.get<string>(
        'MINIO_ENDPOINT',
        'localhost',
      );
      const port = this.configService.get<number>('MINIO_PORT', 9000);
      const useSSL = this.configService.get<boolean>('MINIO_USE_SSL', false);
      const accessKey = this.configService.get<string>('MINIO_ACCESS_KEY');
      const secretKey = this.configService.get<string>('MINIO_SECRET_KEY');
      const bucketName = this.configService.get<string>(
        'MINIO_BUCKET_NAME',
        'flowgenall',
      );

      if (!accessKey || !secretKey) {
        throw new Error('MinIO access key and secret key are required');
      }

      return {
        provider: 'minio',
        minio: {
          endPoint,
          port,
          useSSL,
          accessKey,
          secretKey,
          bucketName,
        },
      };
    } else {
      const region = this.configService.get<string>('OSS_REGION');
      const accessKeyId = this.configService.get<string>('OSS_ACCESS_KEY_ID');
      const accessKeySecret = this.configService.get<string>(
        'OSS_ACCESS_KEY_SECRET',
      );
      const bucketName = this.configService.get<string>('OSS_BUCKET_NAME');
      const endpoint = this.configService.get<string>('OSS_ENDPOINT');

      if (!region || !accessKeyId || !accessKeySecret || !bucketName) {
        throw new Error(
          'OSS region, access key id, access key secret, and bucket name are required',
        );
      }

      return {
        provider: 'oss',
        oss: {
          region,
          accessKeyId,
          accessKeySecret,
          bucketName,
          endpoint,
        },
      };
    }
  }

  /**
   * 初始化存储客户端
   */
  private async initializeStorage(): Promise<void> {
    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }
        this.minioClient = new Minio.Client(this.config.minio);

        // 确保bucket存在
        const bucketExists = await this.minioClient.bucketExists(
          this.config.minio.bucketName,
        );
        if (!bucketExists) {
          await this.minioClient.makeBucket(this.config.minio.bucketName);
          this.logger.log(
            `Created MinIO bucket: ${this.config.minio.bucketName}`,
          );
        }
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }
        this.ossClient = new OSS(this.config.oss);
        this.logger.log('OSS client initialized');
      }

      this.logger.log(
        `Storage service initialized with provider: ${this.config.provider}`,
      );
    } catch (error) {
      this.logger.error('Failed to initialize storage service', error);
      throw error;
    }
  }

  /**
   * 生成唯一存储key
   */
  generateStorageKey(originalName: string, userId: string): string {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8);
    const extension = originalName.split('.').pop();
    const sanitizedName = originalName.replace(/[^a-zA-Z0-9.-]/g, '_');

    return `${userId}/${timestamp}_${random}_${sanitizedName}`;
  }

  /**
   * 上传文件
   */
  async uploadFile(
    buffer: Buffer,
    originalName: string,
    mimeType: string,
    userId: string,
  ): Promise<UploadResult> {
    const storageKey = this.generateStorageKey(originalName, userId);

    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }

        await this.minioClient.putObject(
          this.config.minio.bucketName,
          storageKey,
          buffer,
          buffer.length,
          { 'Content-Type': mimeType },
        );

        return {
          key: storageKey,
          url: `${this.config.minio.useSSL ? 'https' : 'http'}://${this.config.minio.endPoint}:${this.config.minio.port}/${this.config.minio.bucketName}/${storageKey}`,
          size: buffer.length,
          provider: 'minio',
        };
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }

        const result = await this.ossClient.put(storageKey, buffer, {
          headers: { 'Content-Type': mimeType },
        });

        return {
          key: storageKey,
          url:
            result.url ||
            `https://${this.config.oss.bucketName}.${this.config.oss.region}.aliyuncs.com/${storageKey}`,
          size: buffer.length,
          provider: 'oss',
        };
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(`Failed to upload file ${storageKey}`, error);
      throw new Error(`Storage upload failed: ${errorMessage}`);
    }
  }

  /**
   * 下载文件
   */
  async downloadFile(
    storageKey: string,
    filename: string,
  ): Promise<DownloadResult> {
    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }

        const stat = await this.minioClient.statObject(
          this.config.minio.bucketName,
          storageKey,
        );
        const stream = await this.minioClient.getObject(
          this.config.minio.bucketName,
          storageKey,
        );

        return {
          stream: stream,
          contentType:
            (stat.metaData['content-type'] as string) ||
            'application/octet-stream',
          contentLength: stat.size,
          filename,
        };
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }

        const result = await this.ossClient.get(storageKey);
        const stat = await this.ossClient.headObject(storageKey);

        return {
          stream: result.stream as Readable,
          contentType:
            (stat.res.headers['content-type'] as string) ||
            'application/octet-stream',
          contentLength: parseInt(
            (stat.res.headers['content-length'] as string) || '0',
          ),
          filename,
        };
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(`Failed to download file ${storageKey}`, error);
      throw new Error(`Storage download failed: ${errorMessage}`);
    }
  }

  /**
   * 删除文件
   */
  async deleteFile(storageKey: string): Promise<void> {
    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }
        await this.minioClient.removeObject(
          this.config.minio.bucketName,
          storageKey,
        );
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }
        await this.ossClient.delete(storageKey);
      }

      this.logger.log(`File deleted successfully: ${storageKey}`);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(`Failed to delete file ${storageKey}`, error);
      throw new Error(`Storage delete failed: ${errorMessage}`);
    }
  }

  /**
   * 检查文件是否存在
   */
  async fileExists(storageKey: string): Promise<boolean> {
    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }
        await this.minioClient.statObject(
          this.config.minio.bucketName,
          storageKey,
        );
        return true;
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }
        await this.ossClient.headObject(storageKey);
        return true;
      }
    } catch (error) {
      return false;
    }
  }

  /**
   * 获取存储提供商类型
   */
  getProvider(): string {
    return this.config.provider;
  }

  /**
   * 复制文件（用于备份或迁移）
   */
  async copyFile(sourceKey: string, targetKey: string): Promise<void> {
    try {
      if (this.config.provider === 'minio') {
        if (!this.config.minio) {
          throw new Error('MinIO configuration is missing');
        }
        const conditions = new Minio.CopyConditions();
        await this.minioClient.copyObject(
          this.config.minio.bucketName,
          targetKey,
          `/${this.config.minio.bucketName}/${sourceKey}`,
          conditions,
        );
      } else {
        if (!this.config.oss) {
          throw new Error('OSS configuration is missing');
        }
        await this.ossClient.copy(targetKey, sourceKey);
      }

      this.logger.log(`File copied from ${sourceKey} to ${targetKey}`);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Failed to copy file from ${sourceKey} to ${targetKey}`,
        error,
      );
      throw new Error(`Storage copy failed: ${errorMessage}`);
    }
  }
}
